const { log, i18n, events, exec, util } = require("@node-red/util");
const { v4: uuidv } = require('uuid')
var runtime;
var uri;
let _module = "@runtime/lib/causeway"

function init(_runtime, userSettings) {

    log.info(`${_module} initialized causeway runtime `)
    runtime = _runtime
    uri = userSettings["causeway-uri"]
}

function getContext(activeWorkspace) {
    console.log(`retrieving context for ${activeWorkspace}`)
    return runtime.nodes.getContext(activeWorkspace)
}

function updateContext(activeWorkspace, updateDict) {
    try {
        let ctx = runtime.nodes.getContext(activeWorkspace)
        for(let key of Object.keys(updateDict)){
            ctx.set(key, updateDict[key])
        }
        console.log(`successfully updated context for ${activeWorkspace} with the following update dictionary  `, updateDict)
        console.log(ctx.get(Object.keys(updateDict)[0]))
    } catch (exception) {
        throw exception
    }
}


function getContextValue(activeWorkspace, value)
{
    try{
        let ctx=runtime.nodes.getContext(activeWorkspace)
        // console.log(`Context value : `, ctx)
        return ctx.get(value)
    }catch(exception){
        throw exception
    }
}


